const adapter = window.__ai4a11yConfirmActions;
if (!adapter || !adapter.enabled) return true;

const orderBtn = document.getElementById('btn-place-order');
if (!orderBtn) return false;

try {
  adapter.onClick({
    target: orderBtn,
    isTrusted: true,
    timeStamp: performance.now(),
    detail: 0,
    preventDefault() {},
    stopImmediatePropagation() {}
  });

